<?php
use App\Application\Customers\CustomerService;use App\Models\Party;use App\Models\Tenant;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;
uses(RefreshDatabase::class);
test('customer relationship is tenant scoped and has guarded lifecycle',function(){$actor=User::factory()->create();$tenant=Tenant::create(['type'=>'BROKER','legal_name'=>'Client Broker','slug'=>'client-broker','status'=>'ACTIVE','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);$party=Party::create(['type'=>'PERSON','display_name'=>'Client One','legal_identity'=>[],'status'=>'ACTIVE']);$service=app(CustomerService::class);$customer=$service->register($tenant,$party);$service->transition($customer,'SUSPENDED','COMPLIANCE_HOLD','Reviewing identity evidence',$actor);expect($customer->refresh()->status)->toBe('SUSPENDED');expect(fn()=>$service->transition($customer,'ARCHIVED','CUSTOMER_REQUEST','Relationship closed',$actor))->not->toThrow(ValidationException::class);expect(fn()=>$service->transition($customer,'ACTIVE','RESTORE','Invalid restore',$actor))->toThrow(ValidationException::class);});
